namespace GameForge.Gen;

/// <summary>생성 파일을 모아뒀다가 한 번에 디스크로 내보낸다. 재생성 시 항상 덮어쓴다.</summary>
public sealed class Emitter
{
    readonly Dictionary<string, string> _files = new();
    public string Root { get; }

    public Emitter(string root) => Root = root;

    const string Header =
        "// <auto-generated>\n" +
        "//   GameForge 가 기획서(Spec)에서 생성한 파일. 직접 고치지 말 것.\n" +
        "//   수정하려면 Specs/*.json 을 고치고 재생성한다.\n" +
        "// </auto-generated>\n";

    public void Add(string relativePath, string content, bool header = true)
        => _files[relativePath.Replace(@"\", "/")] = header ? Header + content : content;

    public int Flush()
    {
        foreach (var (rel, body) in _files)
        {
            var full = Path.Combine(Root, rel);
            Directory.CreateDirectory(Path.GetDirectoryName(full)!);
            File.WriteAllText(full, body.Replace("\r\n", "\n"));
        }
        return _files.Count;
    }

    public IEnumerable<string> Paths => _files.Keys.OrderBy(p => p);
}
